parameters.query:
select role, content
from (
  select role, content, created_at
  from conversations
  where user_id = '{{ $json.user_id }}'
  order by created_at desc
  limit 6
) recent
order by created_at asc;

parameters.jsCode:
// Turn the last 6 messages into a readable transcript.
// An empty table on a user's first turn is normal, not an error.
const rows = $input.all().map(i => i.json).filter(r => r.role);
const history = rows.length
  ? rows.map(r => `${r.role}: ${r.content}`).join('\n')
  : '(no previous messages)';

return [{ json: {
  question: $('Ask a question').first().json.question,
  user_id: $('Ask a question').first().json.user_id,
  history
}}];

// Format the retrieved chunks as numbered sources the model can cite.
const items = $input.all();

const context = items.map((item, i) => {
  const d = item.json.document || {};
  const m = d.metadata || {};
  return `[${i + 1}] ${m.source} > ${m.section}\n${d.pageContent}`;
}).join('\n\n---\n\n');

// The best similarity score tells the model how confident retrieval was.
// A low top score usually means the answer is not in the documents.
const topScore = Math.max(...items.map(i => Number(i.json.score) || 0));

return [{ json: {
  question: $('Format history').first().json.question,
  user_id: $('Format history').first().json.user_id,
  history: $('Format history').first().json.history,
  search_query: $('Rewrite question').first().json.output,
  context,
  top_score: Math.round(topScore * 1000) / 1000
}}];

